local eventbypass

eventbypass = hookmetamethod(game, "__namecall", function(self, ...)
    local method = getnamecallmethod()
    local args = {...}

    if not checkcaller() and self.Name == "Attack" and method == "FireServer" then
        args[2] = 1 ----Damage You Can Change Don't go above 1 it bans you
        return eventbypass(self, unpack(args))
    end

    return eventbypass(self, unpack(args))
end)

local __namecall; __namecall = hookmetamethod(game,"__namecall",function(self,...)
    local Arguments = {...}
    local Method = tostring(getnamecallmethod():lower())
    if not checkcaller() and Method == "fireserver" and tostring(self) == "Attack" then
        if Arguments[2] == workspace.Beyblades[game:GetService("Players").LocalPlayer.Name] then
            return nil
        end
    end
    return __namecall(self,...)
end)
